import type { BoardAction, Task } from '../types'
import { createDemoTasks } from '../lib/demoTasks'

export interface BoardState {
  tasks: Task[]
}

export function createInitialState(tasks: Task[] = createDemoTasks()): BoardState {
  return { tasks }
}

/**
 * Pure function: same state + same action = same result, no side effects.
 * That is why ids are generated by the caller (`crypto.randomUUID()` is not
 * pure) and why every case returns a new array instead of mutating.
 */
export function boardReducer(state: BoardState, action: BoardAction): BoardState {
  switch (action.type) {
    case 'task_added':
      return { tasks: [...state.tasks, action.task] }

    case 'task_moved': {
      const task = state.tasks.find((item) => item.id === action.id)
      if (!task || task.status === action.to) return state // same reference: React skips the re-render
      // Remove and re-append so the moved task lands at the bottom of its new column.
      const others = state.tasks.filter((item) => item.id !== action.id)
      return { tasks: [...others, { ...task, status: action.to }] }
    }

    case 'task_renamed':
      return {
        tasks: state.tasks.map((task) => (task.id === action.id ? { ...task, title: action.title } : task)),
      }

    case 'task_deleted':
      return { tasks: state.tasks.filter((task) => task.id !== action.id) }

    case 'board_reset':
      return createInitialState()

    default: {
      // If a new action type is added and not handled above,
      // this line stops compiling: `action` is no longer `never`.
      const unhandled: never = action
      return unhandled
    }
  }
}
